/**
 * The contract `switch.tsx` (native) and `switch.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./switch` to
 * `switch.web.tsx` on web — the web file would otherwise import itself.
 */
export type SwitchProps = {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  /** Web only: what a `<label htmlFor>` points at. */
  id?: string | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
};

/** Shared between the two files so the track cannot drift between platforms. */
export const SWITCH_TRACK_CLASS =
  "h-5 w-9 shrink-0 flex-row items-center rounded-full border-2 border-transparent";
export const SWITCH_THUMB_CLASS = "h-4 w-4 rounded-full bg-background";

/**
 * The native switch: a `Pressable` track with a thumb that moves, rather than
 * react-native's `Switch`. RN's takes `trackColor`/`thumbColor` as raw colour
 * values, which would pin the control outside the tailwind theme and make it
 * the one control that does not follow dark mode with the rest.
 *
 * `switch.web.tsx` is radix; `switch-base.ts` holds the contract and the track
 * classes, so the two cannot drift visually.
 */

import { Pressable, View } from "react-native";
import {
  SWITCH_THUMB_CLASS,
  SWITCH_TRACK_CLASS,
  type SwitchProps,
} from "@/components/ui/switch-base";
import { cn } from "@/lib/utils";

function Switch({ checked, onCheckedChange, disabled, className }: SwitchProps) {
  return (
    <Pressable
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onPress={() => onCheckedChange(!checked)}
      className={cn(
        SWITCH_TRACK_CLASS,
        checked ? "bg-primary" : "bg-input",
        // `disabled:` never applies to a Pressable — apply the state directly.
        disabled && "opacity-50",
        className,
      )}
    >
      <View className={cn(SWITCH_THUMB_CLASS, checked ? "ml-4" : "ml-0")} />
    </Pressable>
  );
}

export { Switch };

/**
 * The web switch: radix. `switch.tsx` is the native counterpart and
 * `switch-base.ts` holds the contract they share.
 */

import { Switch as SwitchPrimitive } from "radix-ui";
import {
  SWITCH_THUMB_CLASS,
  SWITCH_TRACK_CLASS,
  type SwitchProps,
} from "@/components/ui/switch-base";
import { cn } from "@/lib/utils";

function Switch({ checked, onCheckedChange, id, disabled, className }: SwitchProps) {
  return (
    <SwitchPrimitive.Root
      id={id}
      checked={checked}
      onCheckedChange={onCheckedChange}
      disabled={disabled}
      className={cn(
        SWITCH_TRACK_CLASS,
        "peer inline-flex cursor-pointer shadow-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=unchecked]:bg-input",
        className,
      )}
    >
      <SwitchPrimitive.Thumb
        className={cn(
          SWITCH_THUMB_CLASS,
          "pointer-events-none block shadow-lg ring-0 transition-transform data-[state=checked]:translate-x-4 data-[state=unchecked]:translate-x-0",
        )}
      />
    </SwitchPrimitive.Root>
  );
}

export { Switch };
